/** @file joinpart.c @brief IRC JOIN/PART with channel and ChanServ policy. */
#include "commands.h"
#include "channel_policy.h"
#include "chanserv.h"
#include "chanserv_db.h"
#include "config.h"
#include "modes.h"
#include "numerics.h"
#include <stdio.h>
#include <string.h>
#include <strings.h>
static int valid_channel_name(const char*n){return n&&strchr(IRC_CHANNEL_PREFIXES,n[0])&&strlen(n)<=IRC_CHANNEL_NAME_MAX&&!strchr(n,' ');}
static void join_one(Server*s,Client*c,const char*n,const char*k,unsigned int depth){Channel*ch;char msg[IRCD_MESSAGE_BUFFER_SIZE];int first,invited;if(!valid_channel_name(n)){client_sendf(c,ERR_NOSUCHCHANNEL,s->config.server_name,c->nick,n?n:"*");return;}if(c->channel_count>=IRC_MAX_CHANNELS_PER_CLIENT){client_sendf(c,ERR_TOOMANYCHANNELS,s->config.server_name,c->nick,n);return;}ch=hash_get(&s->channels_by_name,n);if(!ch){ch=server_get_or_create_channel(s,n);if(ch)chanserv_apply_registration(s,ch);}if(!ch||channel_has_client(ch,c))return;invited=channel_invite_has(ch,c->id);if(ch->key[0]&&(!k||strcmp(ch->key,k))){client_sendf(c,ERR_BADCHANNELKEY,s->config.server_name,c->nick,ch->name);return;}if(channel_client_is_banned(ch,c)){if(ch->ban_redirect[0]&&depth<IRC_JOIN_REDIRECT_MAX&&valid_channel_name(ch->ban_redirect)){client_sendf(c,ERR_LINKCHANNEL,s->config.server_name,c->nick,ch->name,ch->ban_redirect);join_one(s,c,ch->ban_redirect,NULL,depth+1);return;}client_sendf(c,ERR_BANNEDFROMCHAN,s->config.server_name,c->nick,ch->name);return;}if(ch->user_limit&&ch->member_count>=ch->user_limit){if(ch->limit_redirect[0]&&depth<IRC_JOIN_REDIRECT_MAX&&valid_channel_name(ch->limit_redirect)){client_sendf(c,ERR_LINKCHANNEL,s->config.server_name,c->nick,ch->name,ch->limit_redirect);join_one(s,c,ch->limit_redirect,NULL,depth+1);return;}client_sendf(c,ERR_CHANNELISFULL,s->config.server_name,c->nick,ch->name);return;}if(channel_mode_has(ch->modes,CHANNEL_MODE_REGONLY_JOIN)&&!client_mode_has(c->modes,CLIENT_MODE_REGISTERED)){client_sendf(c,ERR_NEEDREGGEDNICK,s->config.server_name,c->nick,ch->name);return;}if(channel_mode_has(ch->modes,CHANNEL_MODE_OPER_ONLY)&&!client_mode_has(c->modes,CLIENT_MODE_OPER|CLIENT_MODE_NETADMIN)){client_sendf(c,ERR_520,s->config.server_name,c->nick,ch->name);return;}if(channel_mode_has(ch->modes,CHANNEL_MODE_ADMIN_ONLY)&&!client_mode_has(c->modes,CLIENT_MODE_NETADMIN)){client_sendf(c,ERR_519,s->config.server_name,c->nick,ch->name);return;}if(channel_mode_has(ch->modes,CHANNEL_MODE_SECURE_ONLY)&&!client_mode_has(c->modes,CLIENT_MODE_SECURE)){client_sendf(c,ERR_SECUREONLYCHAN,s->config.server_name,c->nick,ch->name);return;}if(channel_mode_has(ch->modes,CHANNEL_MODE_INVITE_ONLY)&&!invited&&!channel_client_is_invex(ch,c)){client_sendf(c,ERR_INVITEONLYCHAN,s->config.server_name,c->nick,ch->name);return;}if(!channel_join_throttle_allows(ch,c->id)){client_sendf(c,ERR_TOOMANYJOINS,s->config.server_name,c->nick,ch->name);return;}first=ch->member_count==0;if(channel_add_client(ch,c)<0)return;channel_join_throttle_record(ch,c->id);if(invited)channel_invite_consume(ch,c->id);if(first&&!channel_mode_has(ch->modes,CHANNEL_MODE_REGISTERED))channel_add_privileges(ch,c,CHANNEL_PRIV_OWNER|CHANNEL_PRIV_OPERATOR);else if(channel_mode_has(ch->modes,CHANNEL_MODE_REGISTERED)&&c->account_name[0]){ChanServDb db={0};ChanServChannel r;if(chanserv_db_open(&db,s->config.chanserv_db)==0){if(chanserv_db_get(&db,ch->name,&r)==1&&r.enabled&&strcasecmp(r.founder,c->account_name)==0)channel_add_privileges(ch,c,CHANNEL_PRIV_OWNER|CHANNEL_PRIV_OPERATOR);chanserv_db_close(&db);}}
snprintf(msg,sizeof(msg),":%s!%s@%s JOIN %s\r\n",c->nick,c->user,c->display_host,ch->name);channel_broadcast(ch,NULL,msg);if(!ch->topic[0])client_sendf(c,RPL_NOTOPIC,s->config.server_name,c->nick,ch->name);else{client_sendf(c,RPL_TOPIC,s->config.server_name,c->nick,ch->name,ch->topic);client_sendf(c,RPL_TOPICWHOTIME,s->config.server_name,c->nick,ch->name,ch->topic_setter,(unsigned long)ch->topic_time);}command_send_names(ch,c);}
CommandResult command_join(Server*s,Client*c,char*p){char*n,*k;if(command_require_registered(c))return COMMAND_KEEP_CLIENT;if(!p){client_sendf(c,ERR_NEEDMOREPARAMS,s->config.server_name,c->nick,"JOIN");return COMMAND_KEEP_CLIENT;}n=strtok(p," ");k=strtok(NULL," ");join_one(s,c,n,k,0);return COMMAND_KEEP_CLIENT;}
CommandResult command_part(Server*s,Client*c,char*p){char*n,*r;Channel*ch;char m[IRCD_MESSAGE_BUFFER_SIZE];if(command_require_registered(c))return COMMAND_KEEP_CLIENT;if(!p){client_sendf(c,ERR_NEEDMOREPARAMS,s->config.server_name,c->nick,"PART");return COMMAND_KEEP_CLIENT;}n=strtok(p," ");r=strtok(NULL,"");if(r&&*r==':')++r;ch=hash_get(&s->channels_by_name,n);if(!ch){client_sendf(c,ERR_NOSUCHCHANNEL,s->config.server_name,c->nick,n);return COMMAND_KEEP_CLIENT;}if(!channel_has_client(ch,c)){client_sendf(c,ERR_NOTONCHANNEL,s->config.server_name,c->nick,ch->name);return COMMAND_KEEP_CLIENT;}snprintf(m,sizeof(m),":%s!%s@%s PART %s :%s\r\n",c->nick,c->user,c->display_host,ch->name,r?r:IRC_DEFAULT_PART_REASON);channel_broadcast(ch,NULL,m);channel_remove_client(ch,c);server_remove_channel_if_empty(s,ch);return COMMAND_KEEP_CLIENT;}
